!function(){"use strict";const e={tier1:{title:"Tier 1: Upper Canopy Surge (70m)",sub:"Shola Forest Headwater Inflow",desc:"Originating from the pristine Chembra Peak watershed, the torrential streams cascade over ancient Western Ghats granulite rocks surrounded by tea estates and evergreen shola tree canopies.",drop:"Approx. 70 meters",habitat:"Wet Evergreen & Montane Shola Forests",highlight:"Roaring white curtain through tree ferns"},tier2:{title:"Tier 2: Sentinel Rock Funnel (65m)",sub:"Mid-Gorge Chasm & Needle Cliff",desc:"The cascade narrows forcefully alongside the iconic needle-pointed Sentinel Rock cliff face. High kinetic pressure creates continuous water spray and carved rock pools.",drop:"Approx. 65 meters",habitat:"Rocky Gorges & Wet Mossy Cliffs",highlight:"Sentinel Rock needle formation & rock climbing point"},tier3:{title:"Tier 3: Lower Plunge Pool Cascade (65m)",sub:"Bottom Plunge Basin & Swimming Zone",desc:"The final drop crashes into a wide, boulder-strewn natural pool before joining the Chaliyar River drainage network. Tourists can safely swim under lifeguard supervision.",drop:"Approx. 65 meters (Total 200m / 656 ft)",habitat:"Riparian Riverbank & Boulders",highlight:"Natural rock swimming pool & rafting launch"}},t={falls:{title:"Soochipara Main Cascade (200m Drop)",sub:"Sentinel Rock Waterfalls Core Drop",desc:"Surrounded by deciduous and wet evergreen forests in Meppadi panchayat, this multi-tier waterfall plunges into a refreshing rocky pool before flowing down as a tributary of the Chaliyar River.",loc:"Vellarimala, Meppadi, Wayanad",dist:"2 km (Paved forest trail with steps)",high:"Natural pool bath, mist spray, evergreen views"},"sentinel-rock":{title:"Sentinel Rock Peak",sub:"Needle-Pointed Granite Monolith",desc:"A massive needle-shaped rock protrusion standing guard over the waterfall gorge, offering world-class natural rock-climbing challenges and stunning horizon vistas.",loc:"Gorge Overlook Crest",dist:"Adjoining waterfall drop point",high:"Rock climbing, geological monolith, eagle roost"},"entry-gate":{title:"Forest Department Checkpoint & Parking",sub:"Trailhead & Eco-Tourism Counter",desc:"The starting point for the 2 km downhill forest trek. Features visitor vehicle parking, ticket counters, local spice shops, and plastic inspection security.",loc:"Soochipara Forest Gate, Meppadi",dist:"0 km (Trailhead start)",high:"Eco-passes, local snacks & cloakrooms"},chembra:{title:"Chembra Peak Watershed",sub:"Highest Peak in Wayanad (2,100 m)",desc:"The pristine mountain range directly replenishing the headstreams of Soochipara Falls, famous for its heart-shaped natural lake (Hridaya Saras).",loc:"Chembra Range, Meppadi",dist:"15 km via trekking ridge",high:"Heart lake, panoramic mountain trek"},meenmutty:{title:"Meenmutty Falls (300m)",sub:"Largest 3-Tier Waterfall in Wayanad",desc:"A monumental 300-meter three-stage cascade located 12 km from Soochipara, reachable through a challenging jungle trek near Banasura Sagar.",loc:"Near Korome, Wayanad",dist:"12 km along Vellarimala belt",high:"Largest 3-tier drop in Wayanad"}},n={"post-monsoon":{title:"Post-Monsoon & Winter Peak (September to February)",desc:"The ideal season to explore Soochipara Falls. The waterfall flows with immense volume and crystal-clear emerald water. Lush green shola forests thrive, trekking paths are safe and dry, and visitors can enjoy bathing under the lower plunge pool.",flow:"Flow: Robust, Clear & Roaring",trek:"Trek Trail: Safe, Dry & Picturesque",highlight:"Highlights: Natural pool swimming, rock photography & tea estate walk"},monsoon:{title:"Heavy Southwest Monsoon (June to August)",desc:"Torrential downpours in the Western Ghats cause the waterfall to surge with overwhelming fury. Rocks become slippery, flash floods can occur, and the forest department often closes the trail for public safety.",flow:"Flow: Extreme Thunderous Deluge",trek:"Trek Trail: Slippery with leeches; periodic entry closures",highlight:"Highlights: Untamed raw power & misty rainforest ambiance"},summer:{title:"Summer Exploration (March to May)",desc:"Water flow thins down into clear, gentle rivulets. The forest temperature remains pleasantly cool compared to plains, making it a peaceful getaway with easy wading in the plunge basin.",flow:"Flow: Moderate to Mild Streams",trek:"Trek Trail: Dry & accessible for all age groups",highlight:"Highlights: Relaxed family bathing & unhurried birdwatching"}};document.addEventListener("DOMContentLoaded",function(){const a=document.querySelectorAll(".tier-block"),o=document.getElementById("tier-title"),i=document.getElementById("tier-sub"),r=document.getElementById("tier-body"),s=document.getElementById("tier-drop"),l=document.getElementById("tier-habitat"),c=document.getElementById("tier-highlight"),d=document.querySelectorAll(".map-pin"),h=document.getElementById("spot-title"),g=document.getElementById("spot-sub"),u=document.getElementById("spot-body"),m=document.getElementById("spot-loc"),p=document.getElementById("spot-dist"),f=document.getElementById("spot-high"),y=document.querySelectorAll(".season-btn"),k=document.getElementById("s-card-title"),b=document.getElementById("s-card-desc"),w=document.getElementById("sp-flow"),v=document.getElementById("sp-trek"),E=document.getElementById("sp-highlight"),C=document.getElementById("theme-toggle");C&&C.addEventListener("click",function(){document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark")}),a.forEach(function(t){t.addEventListener("click",function(){a.forEach(e=>e.classList.remove("active")),t.classList.add("active");const n=t.getAttribute("data-tier"),d=e[n];d&&(o&&(o.textContent=d.title),i&&(i.textContent=d.sub),r&&(r.innerHTML=`<p>${d.desc}</p>`),s&&(s.textContent=d.drop),l&&(l.textContent=d.habitat),c&&(c.textContent=d.highlight))}),t.addEventListener("keydown",function(e){"Enter"!==e.key&&" "!==e.key||(e.preventDefault(),t.click())})}),d.forEach(function(e){e.addEventListener("click",function(){const n=e.getAttribute("data-spot"),a=t[n];a&&(h&&(h.textContent=a.title),g&&(g.textContent=a.sub),u&&(u.innerHTML=`<p>${a.desc}</p>`),m&&(m.textContent=a.loc),p&&(p.textContent=a.dist),f&&(f.textContent=a.high))}),e.addEventListener("keydown",function(t){"Enter"!==t.key&&" "!==t.key||(t.preventDefault(),e.click())})}),y.forEach(function(e){e.addEventListener("click",function(){y.forEach(e=>e.classList.remove("active")),e.classList.add("active");const t=e.getAttribute("data-season"),a=n[t];a&&(k&&(k.textContent=a.title),b&&(b.textContent=a.desc),w&&(w.textContent=a.flow),v&&(v.textContent=a.trek),E&&(E.textContent=a.highlight))})});const S=document.getElementById("menu-toggle"),T=document.getElementById("nav-menu");S&&T&&S.addEventListener("click",()=>T.classList.toggle("active"))})}();